PREFIX = {"exploring-data": "u1", "sampling-experimentation": "u2", AP: "u3", SI: "u4"}


def build():
    allp = dict(A.PARTNER); allp.update(PARTNER)
    alle = dict(A.ERRORS); alle.update(ERRORS)
    for u, rows in allp.items():
        for k, lv, pa, ea, pb, eb, ans, sa, sb in rows:
            pid = f"PC-{PREFIX[u]}-s{k:02d}-{lv}"
            for role, pr, ex, st_ in (("A", pa, ea, sa), ("B", pb, eb, sb)):
                SA(u, k, lv, f"Partner {role}. {pr}", ans, [st_], family=f"{PREFIX[u]}_s{k:02d}_partner", std=STD[u][k],
                   check={"kind": "expr", "expr": ex, "no_print_check": "partner"} if ex else None,
                   note=f"Partner Check pair {pid} ({role}); both partners' answers must match.")
    for u, rows in alle.items():
        for k, lv, pr, ans, steps, ex in rows:
            SA(u, k, lv, pr, ans, steps, family=f"{PREFIX[u]}_s{k:02d}_ea_error", std=STD[u][k],
               check={"kind": "expr", "expr": ex, "no_print_check": "error analysis", "skip_distractors": True} if ex else None)
